import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

const String kPaytmQrBase64 = '';

class PaymentQrImageWidget extends StatelessWidget {
  final double? height;
  final double? width;
  final BoxFit fit;

  const PaymentQrImageWidget({
    super.key,
    this.height,
    this.width,
    this.fit = BoxFit.contain,
  });

  static Uint8List? _cachedBytes;

  static Uint8List get qrBytes {
    _cachedBytes ??= base64Decode(kPaytmQrBase64);
    return _cachedBytes!;
  }

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      qrBytes,
      height: height,
      width: width,
      fit: fit,
      errorBuilder: (context, error, stackTrace) {
        return Container(
          height: height ?? 200,
          width: width,
          color: Colors.grey.shade100,
          child: const Center(
            child: Icon(Icons.qr_code_2_rounded, size: 80, color: Color(0xFF002970)),
          ),
        );
      },
    );
  }
}